let serial=0;
function add(id,prompt,answer,wrong,clue,rule,model,relationship,skill,extra={}){
 const options=wrong.map(([s])=>s);options.splice(serial++%5,0,answer);
 const q={type:'single',prompt,instructions:'Choose the single best answer using the complete context.',options,answer,skill,vocabulary:[],source:{kind:'original-format-practice',formatReferences:refs[id]},explanation:{relationship,clue,rule,model,rejects:wrong.map(([option,reason])=>({option,reason}))},...extra};banks[id].push(q);return q;
}
function gap(id,prompt,answer,wrong,clue,rule,skill){return add(id,prompt,answer,wrong,clue,rule,prompt.replace('___',answer),'Context and construction: keep the intended action and direction',skill);}
function combo(id,prompt,sentences,valid,reasons,models,incorrect=false){
 const permutation=[[0,1,2],[2,0,1],[0,2,1]][serial%3];
 if(sentences.length===3){sentences=permutation.map(i=>sentences[i]);valid=permutation.map(i=>valid[i]);reasons=permutation.map(i=>reasons[i]);models=permutation.map(i=>models[i]);}
 const labels=sentences.map((_,i)=>['I','II','III','IV'][i]),label=ls=>ls.length?ls.join(' and ')+' only':'None';
 const selected=labels.filter((_,i)=>incorrect?!valid[i]:valid[i]),answer=label(selected),poss=[];
 for(let mask=0;mask<(1<<labels.length);mask++)poss.push(labels.filter((_,i)=>mask&(1<<i)));
 const wrong=poss.map(label).filter(s=>s!==answer).slice(0,4).map(s=>[s,'This is not the complete required set. '+labels.map((l,i)=>l+': '+reasons[i]).join(' ')]);
 const q=add(id,prompt,answer,wrong,'Check each statement independently before selecting a combination.','A combination must contain every required statement and no extra one.',models.join(' '),incorrect?'Direction: select INCORRECT statements':'Direction: select CORRECT statements',id==='idioms-phrasal'?'phrasal usage combination':'confusable usage combination',{selectionDirection:incorrect?'incorrect':'correct',candidates:sentences.map((text,i)=>({label:labels[i],text,valid:valid[i],reason:reasons[i]}))});
 q.instructions=`Choose all and only the ${incorrect?'incorrect':'correct'} statements. In the explanation, valid means the sentence is correct.`;
 return q;
}

