function vocabItem(p,answer,wrongs,clue,opposite=false){
 const target=p.match(/\[([^\]]+)\]/)[1];
 const q=add('context-vocabulary',p,answer,wrongs.map(w=>{if(!gloss[w])throw Error('Missing gloss '+w);return [w,`“${w}” means ${gloss[w]}. It does not ${opposite?'give the requested opposite':'preserve the required contextual meaning'}. ${clue}`];}),clue,'Match the contextual sense and grammatical role. A related word, a stronger claim and a word with the opposite direction are different choices.',opposite?`Original contextual word: ${target}. Requested opposite: ${answer}.`:p.replace('['+target+']',answer),opposite?'ANTONYM: choose the contextual opposite':'SYNONYM: preserve the contextual meaning',opposite?'contextual antonym':'contextual synonym',{lexical:{target,direction:opposite?'opposite':'nearest'}});
 q.instructions=`Choose the ${opposite?'OPPOSITE':'NEAREST'} meaning of the word in square brackets AS USED HERE.`;
 if(opposite)q.explanation.modelLabel='Meaning contrast';
}
synRows.forEach(r=>vocabItem(...r));
