const mixed='advanced-mixed';
function errorCount(clean,edits){
 let prompt=clean;for(const [correction,incorrect]of edits){if(prompt.split(correction).length!==2)throw Error('Nonunique error span '+correction);prompt=prompt.replace(correction,incorrect);}
 const n=edits.length,label=x=>x===1?'1 error':x+' errors';
 const issues=edits.map(([correction,incorrect,reason])=>({incorrect,correction,reason}));
 const clue=n?issues.map((e,i)=>`${i+1}. “${e.incorrect}” → “${e.correction}”: ${e.reason}`).join(' '):'All subjects, verb forms, complements and paired structures are acceptable; do not invent an error.';
 const q=add(mixed,prompt,label(n),[0,1,2,3,4].filter(x=>x!==n).map(x=>[label(x),`The paragraph contains ${n} independently faulty phrase${n===1?'':'s'}, not ${x}. ${clue}`]),clue,'Count each independently faulty phrase once. A phrase that violates two related descriptions of the same construction is still one faulty phrase; do not count mere style preferences.',clean,'Count independently incorrect phrases, not the number of sentences','paragraph error count',{grammarIssues:issues});
 q.instructions='How many independently faulty grammatical phrases occur? Count each separately faulty phrase once; ignore stylistic preferences. The paragraph may contain no errors.';q.explanation.modelLabel='Correct paragraph';
}
