function multiError(parts,corrections){
 const labels=['A','B','C','D'],bad=Object.keys(corrections),name=ls=>ls.length?ls.join(' and ')+' only':'No error',answer=name(labels.filter(l=>bad.includes(l)));
 const pools=[[],['A'],['B'],['C'],['D'],['A','B'],['A','C'],['A','D'],['B','C'],['B','D'],['C','D'],labels];
 const reasons=labels.map((l,i)=>corrections[l]?`Replace “${parts[i]}” with “${corrections[l].text}”. ${corrections[l].reason}`:`Part ${l} is acceptable as written.`);
 const q=add(mixed,'Identify ALL incorrect parts of the sentence formed by reading A–D in order.',answer,pools.map(name).filter(x=>x!==answer).slice(0,4).map(x=>[x,'Check every part. '+reasons.join(' ')]),labels.map((l,i)=>l+': '+reasons[i]).join(' '),'Judge each labelled part, then select every incorrect part. Do not stop after finding one error.',parts.map((s,i)=>corrections[labels[i]]?.text||s).join(' '),'Direction: select all INCORRECT parts','multiple-error parts',{selectionDirection:'incorrect',candidates:parts.map((text,i)=>({label:labels[i],text,valid:!bad.includes(labels[i]),reason:reasons[i]})),partCorrections:corrections});
 q.instructions='Read A–D as one sentence. Select every part containing an error, or No error when all four are correct.';
}
