function hybrid(sentences,word,alternatives,clue,replace=null){
 const count=banks[mixed].length,perm=[[2,0,1],[1,2,0],[1,0,2]][count%3],labels=['A','B','C'];
 const parts=Object.fromEntries(labels.map((l,i)=>[l,sentences[perm[i]]]));
 const order=sentences.map((_,i)=>labels[perm.indexOf(i)]),render=(o,w)=>o.map(l=>parts[l].replace('___',w)).join(' ');
 const option=(o,w)=>o.join('')+' / '+w,answer=option(order,word),wrongOrder1=[order[1],order[0],order[2]],wrongOrder2=[order[0],order[2],order[1]];
 const wrong=[[option(order,alternatives[0][0]),alternatives[0][1]],[option(order,alternatives[1][0]),alternatives[1][1]],[option(wrongOrder1,word),'This reverses the introductory event and its dependent response. '+clue],[option(wrongOrder2,word),'This presents the consequence before the step it depends on. '+clue]];
 const shown=Object.entries(parts).map(([l,s])=>l+'. '+(replace?s.replace('___','['+replace+']'):s)).join('\n');
 const q=add(mixed,`Choose BOTH the correct sentence order and the ${replace?'replacement for the bracketed word':'completion of the blank'}.\n\n${shown}`,answer,wrong,clue,'Solve the reference chain and word choice independently, then verify that the selected option satisfies BOTH.',render(order,word),'Hybrid: coherence plus contextual word choice',replace?'order plus replacement':'order plus filler',{hybrid:{kind:replace?'replacement':'filler',parts,order,word,replace}});q.explanation.modelLabel='Correct paragraph';
 q.instructions='Each option gives ORDER / WORD. Use every sentence once and complete both tasks, not just the ordering.';
}
