hybrid(['An unverified rumour claimed that the bank would close.','The bank checked the facts and found the claim false.','It issued a lucid statement to ___ the rumour.'],'dispel',[['obfuscate','Obfuscate makes an issue unclear instead of removing a false rumour.'],['substantiate','Substantiate would support the claim already found false.']],'The rumour must be introduced before its checking; the corrective statement follows the finding that the claim was false.','obfuscate');
hybrid(['The board was concerned about a possible cash shortage.','To guard against that risk, it retained an emergency reserve.','This ___ choice protected essential payments during an outage.'],'prudent',[['reckless','Retaining a protective reserve is not disregard for risk.'],['credulous','Credulous means too ready to believe, not cautious about cash risk.']],'That risk refers to the shortage; this choice refers to retaining the reserve and is sensibly cautious.','reckless');
hybrid(['The auditor checked every entry against its original receipt.','For each mismatch, she examined the source record again.','This ___ review identified even small discrepancies.'],'meticulous',[['perfunctory','Perfunctory means lacking care; every entry and re-examination show the opposite.'],['cursory','Cursory means superficial, contrary to checking every source record.']],'Each mismatch depends on the entry check; this review summarises both detailed actions.','perfunctory');
hybrid(['Two major cost components had not yet been calculated.','The panel therefore refused to treat the estimate as final.','Its finding remained ___ pending those missing figures.'],'tentative',[['definitive','Definitive would mean final, explicitly withheld.'],['conclusive','Conclusive would settle the matter despite the missing inputs.']],'Missing costs cause refusal of final status; its finding refers to the panel and remains provisional.','definitive');
hybrid(['A borrower reported an incorrect debit.','The bank confirmed the error by reviewing the payment record.','It refunded the excess amount to ___ the loss.'],'redress',[['exacerbate','Exacerbate would worsen the loss; a refund remedies it.'],['defer','Defer postpones action rather than remedies the financial loss.']],'The debit precedes the confirming review; the refund then remedies the confirmed loss.','exacerbate');

function wordRestore(template,correctWords,shownOrder){
 const labels=['A','B','C','D'],shown=shownOrder.map(i=>correctWords[i]);
 const repair=correctWords.map(w=>labels[shown.indexOf(w)]),identity=[...labels];
 const all=[identity,['B','A','C','D'],['A','C','B','D'],['A','B','D','C'],['C','A','B','D'],['D','C','B','A'],['B','A','D','C']];
 const name=o=>o.join(', '),answer=name(repair),wrongs=[...new Map(all.map(o=>[name(o),o])).values()].filter(o=>name(o)!==answer).slice(0,4);
 const render=ws=>template.replace(/\{([A-D])\}/g,(_,l)=>ws[labels.indexOf(l)]);
 const wrong=wrongs.map(o=>{const words=o.map(l=>shown[labels.indexOf(l)]),bad=labels.find((l,i)=>words[i]!==correctWords[i]);return [name(o),`This leaves “${words[labels.indexOf(bad)]}” at ${bad}, where the context requires “${correctWords[labels.indexOf(bad)]}”. Check every labelled position.`];});
 const q=add(mixed,render(shown.map((s,i)=>s+' ('+labels[i]+')')),answer,wrong,'Distinguish investigating, performing, postponing, cancelling and excluding. Each action has its own contextual cue.','Options give the original labels to place at A, B, C and D, in that order. A, B, C, D leaves the words unchanged.',render(correctWords),'Restore ALL labelled words; one successful swap may be insufficient','multi-word phrasal restoration',{restoration:{template,shown,correctWords,repair}});
 q.instructions='Each option lists the original word labels to place at A, B, C and D, respectively. Every original word is used once. A, B, C, D means no change.';
}
wordRestore('The investigator will {A} the complaint, the audit team will {B} the required checks, the panel will {C} the hearing until Friday, and the bank will {D} the abandoned launch altogether.',['look into','carry out','put off','call off'],[1,0,2,3]);
wordRestore('The panel must {A} a plan by drafting it, {B} costs by considering them, {C} the scheme permanently by abolishing it, and {D} a possibility by excluding it.',['draw up','take into account','do away with','rule out'],[2,0,1,3]);
wordRestore('The firm may {A} funds if they are exhausted, {B} a reserve by saving money for later, {C} an issue by raising it at a meeting, and {D} a request by rejecting it.',['run out of','set aside','bring up','turn down'],[1,0,3,2]);
wordRestore('The regulator will {A} the complaint by investigating it, {B} the unused proposal by rejecting it, {C} the review by performing it, and {D} the hearing by postponing it.',['look into','turn down','carry out','put off'],[0,1,2,3]);
wordRestore('The bank will {A} the error by investigating it, {B} the lost records by locating them through a search, {C} the incorrect debit by explaining its cause, and {D} a new plan by drafting it.',['look into','track down','account for','draw up'],[1,2,3,0]);

const dualRows=[
 ['The initial finding was [conclusive] because key records were still missing.','The final explanation was [opaque] and easy for every applicant to understand.','tentative','lucid','conclusive','opaque','Missing records limit finality; easy to understand establishes clarity.'],
 ['The design was technically [plausible] because engineers had proved it could be built.','The account sounded [feasible], but no independent evidence supported it.','feasible','plausible','plausible','feasible','Practical construction takes feasible; an apparently believable account takes plausible.'],
 ['The bank had enough assets to meet total debts and was therefore [liquid].','It could not pay salaries immediately because it lacked [solvency].','solvent','liquidity','liquid','solvency','Total debt capacity is solvency; immediately available funds are liquidity.'],
 ['The extra review will [compliment] the first by adding independent evidence.','The manager offered a [complement] to praise the officer’s care.','complement','compliment','compliment','complement','An addition complements; praise is a compliment.'],
 ['The officer was [discrete] and protected the customer’s private information.','The sample was divided into three [discreet] groups with no overlap.','discreet','discrete','discrete','discreet','Privacy-related care is discreet; separate categories are discrete.']
];
dualRows.forEach(([one,two,a,b,oldA,oldB,clue])=>{
 const opt=(x,y)=>`I: ${x}; II: ${y}`,answer=opt(a,b),alternatives=[[oldA,b],[a,oldB],[oldA,oldB],[b,a]];
 const unique=[...new Map(alternatives.map(p=>[opt(...p),p])).values()].filter(p=>opt(...p)!==answer);
 // Add an explicitly unchanged phrase when a two-way contrast makes a duplicate distractor.
 while(unique.length<4)unique.push(unique.length===3?[a,'No replacement']:[oldA,'No replacement']);
 const q=add(mixed,'Correct BOTH bracketed words.\nI. '+one+'\nII. '+two,answer,unique.map(([x,y])=>[opt(x,y),`This does not repair both meanings. ${clue}`]),clue,'Check each statement independently. A pair with only one correct replacement is not the answer.',one.replace('['+oldA+']',a)+' '+two.replace('['+oldB+']',b),'Dual correction: both contextual choices must fit','dual contextual replacement',{dual:{sentences:[one,two],originals:[oldA,oldB],replacements:[a,b]}});q.explanation.modelLabel='Correct sentences';
});

const existing=read('vocabulary.json');
const selected=[
 ['rule out','exclude something as a possibility',['rule out an explanation / rule it out'],['ruled out','ruling out'],'The missing receipt did not rule out a valid payment, so the auditor checked the transaction log.'],
 ['carry out','perform or complete a task or instruction',['carry out an audit / carry the checks out'],['carried out','carrying out'],'The independent team will carry out the audit before the funds are released.'],
 ['look into','investigate or examine a matter',['look into a complaint / look into it'],['looked into','looking into'],'The bank agreed to look into the unexplained charge and examine the payment records.'],
 ['at stake','at risk or dependent on the outcome',['savings at stake / public confidence at stake'],[],'With public confidence at stake, the bank published a clear account of the error.'],
 ['credulous','too ready to believe claims without sufficient checking',['credulous customers / a credulous listener'],[],'Credulous customers accepted the unverified message without checking who had sent it.'],
 ['discreet','careful and tactful about what is said or disclosed',['a discreet officer / discreet handling'],['discreetly'],'The discreet officer protected the borrower’s private information during the enquiry.'],
 ['adverse','harmful or unfavourable',['an adverse effect / adverse conditions'],['adversely'],'The unexplained delay had an adverse effect on borrower confidence.'],
 ['complement','add something useful that completes or improves something else',['complement a review / complement existing safeguards'],['complements','complemented','complementary'],'The independent audit will complement the internal review by providing additional evidence.']
].map(([term,meaning,collocations,forms,readingExample])=>({term,meaning:existing.find(v=>v.term===term)?.meaning||meaning,collocations,forms,important:true,readingExample}));
const info={
 'idioms-phrasal':['Idioms & phrasal verbs','I',['Investigate, perform and postpone','Plans, follow-up and resources','Risk, authority and empty promises','Actions and practical consequences','Interpret the whole expression','Degree, priority and evidence','Phrasal verbs: pronoun placement','Valid alternatives and incorrect directions']],
 'context-vocabulary':['Synonyms & antonyms','V',['Meaning and direction','Believability, practicality and clarity','Care, coverage and certainty','Evidence, removal and timing','Fairness, finance and remedies','Opposites: meaning, not word association','Opposites: degree and stability','Opposites: recovery, inequality and openness']],
 'spelling-confusables':['Spelling & confused words','B',['Double letters and vowel patterns','Administrative spelling','Difficult endings and silent letters','Loan terms, influence and belief','Disclosure, reassurance and access','Order, advice and word forms','Judge every use','Valid senses and incorrect-use combinations']],
 'advanced-mixed':['Advanced mixed practice','X',['Paragraph error counts','No error and multiple independent errors','Identify every incorrect part','Multiple errors: clauses and parallelism','Order plus a contextual filler','Order plus contextual replacement','Restore every phrasal expression','Dual corrections: neither half is enough']]
};
for(const id of ids){
 const [title,prefix,titles]=info[id],qs=banks[id];if(qs.length!==40)throw Error(id+': expected 40, got '+qs.length);
 const candidates=selected.filter(v=>qs.some(q=>[v.term,...v.forms].some(f=>hasTerm(JSON.stringify(q),f))));
 const c={id,title,description:'40 original learning questions based on the planned non-RC coverage. Warm-ups, application and harder combinations share the same instant-feedback UI; levels are approximate, not an exact exam simulation.',source:{kind:'original-format-practice',formatReferences:refs[id]},vocabularyCandidates:candidates,packs:[]};
 for(let i=0;i<8;i++){const p={id:prefix+String(i+1).padStart(2,'0'),title:titles[i],level:id==='advanced-mixed'?(i<2?'Mains-style':'Higher practice'):i<2?'Warm-up':i<6?'Mains-style':'Higher practice',questions:qs.slice(i*5,i*5+5)};p.questions.forEach((q,j)=>{q.id=id+'/'+p.id+'-Q'+(j+1);q.vocabulary=[...new Set([...existing.filter(v=>hasTerm(q.prompt+' '+q.explanation.model,v.term)).map(v=>v.term),...candidates.filter(v=>[v.term,...v.forms].some(f=>hasTerm(JSON.stringify(q),f))).map(v=>v.term)])];});c.packs.push(p);}
 write('chapters/'+id+'.json',c);
}
